"use strict";const langs=["en", "ar", "tr", "fr", "es", "de", "it", "pt", "nl", "ru", "uk", "pl", "cs", "ro", "hu", "el", "sv", "da", "no", "fi", "bg", "sr", "hr", "he", "fa", "ur", "hi", "bn", "id", "ms", "zh", "ja"];const code=(navigator.languages||[navigator.language]).map(x=>x.toLowerCase().split("-")[0]).map(x=>["nb","nn"].includes(x)?"no":x).find(x=>langs.includes(x))||"en";location.replace(new URL(code+"/index.html"+location.hash,location.href).href);